import{af as t,z as o,J as i,ab as r}from"./chunks/framework.T3M3Y_he.js";const v=JSON.parse('{"title":"Connectivity","description":"","frontmatter":{"aside":false},"headers":[],"relativePath":"faq/connectivity.md","filePath":"faq/connectivity.md"}'),a={name:"faq/connectivity.md"};function n(c,e,h,s,l,d){return o(),i("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792754976000"},[...e[0]||(e[0]=[r('<h1 id="connectivity" tabindex="-1">Connectivity <a class="header-anchor" href="#connectivity" aria-label="Permalink to &quot;Connectivity&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#do-the-devices-have-bluetooth-connectivity">Do the devices have Bluetooth connectivity? ​</a></li><li><a href="#do-the-devices-need-internet-to-work">Do the devices need internet to work? ​</a></li><li><a href="#will-the-devices-work-in-remote-poor-signal-area">Will the devices work in remote/poor signal area? ​</a></li><li><a href="#will-the-device-work-indoors">Will the device work indoors? ​</a></li><li><a href="#which-countries-do-lightbug-products-work-in">Which countries do LightBug products work in? ​</a></li></ul></nav><h2 id="do-the-devices-have-bluetooth-connectivity" tabindex="-1">Do the devices have Bluetooth connectivity? <a class="header-anchor" href="#do-the-devices-have-bluetooth-connectivity" aria-label="Permalink to &quot;Do the devices have Bluetooth connectivity?&quot;">​</a></h2><p>Yes, at the time of writing all of our core devices have Bluetooth connectivity</p><p>This enables features like short range location searching, mobile safe-zone and remote controlled alarm to help you find it.</p><p>Be sure to check the <a href="/docs/pr/27/devices">individual device pages</a> for the most up-to-date information.</p><h2 id="do-the-devices-need-internet-to-work" tabindex="-1">Do the devices need internet to work? <a class="header-anchor" href="#do-the-devices-need-internet-to-work" aria-label="Permalink to &quot;Do the devices need internet to work?&quot;">​</a></h2><p>Each device works by sending information via the internet. Our SIM cards can roam across many networks in different countries and will pick the network with the strongest signal, rather than being tied to a single operator. Our devices do not work so well in remote areas with little/no cell coverage, as they need the internet to connect.</p><p>Unlike many GPS trackers, our devices have their own internet connection.</p><p>They do not rely on Bluetooth or being near a mobile phone.</p><h2 id="will-the-devices-work-in-remote-poor-signal-area" tabindex="-1">Will the devices work in remote/poor signal area? <a class="header-anchor" href="#will-the-devices-work-in-remote-poor-signal-area" aria-label="Permalink to &quot;Will the devices work in remote/poor signal area?&quot;">​</a></h2><p>Lightbug devices do not work so well in remote areas with little to no cell coverage, as they need the internet to connect.</p><p>Luckily, with over 600 network partners globally, this is a rare occurrence!</p><h2 id="will-the-device-work-indoors" tabindex="-1">Will the device work indoors? <a class="header-anchor" href="#will-the-device-work-indoors" aria-label="Permalink to &quot;Will the device work indoors?&quot;">​</a></h2><p>Our trackers work both indoors and outdoors.</p><p>They use <a href="/docs/pr/27/terminology/positioning/gnss">GPS/GNSS</a> to locate themselves outdoors and <a href="/docs/pr/27/terminology/positioning/wifi">WPS (WiFi Positioning System)</a> when indoors.</p><p>Typical accuracy outdoors is 1-5m, and 10-30m indoors.</p><p>If you need better accuracy indoors, <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">get in touch</a>!</p><h2 id="which-countries-do-lightbug-products-work-in" tabindex="-1">Which countries do LightBug products work in? <a class="header-anchor" href="#which-countries-do-lightbug-products-work-in" aria-label="Permalink to &quot;Which countries do LightBug products work in?&quot;">​</a></h2><p>Lightbug devices feature <a href="https://lightbug.io/feature/worldwide-coverage/" target="_blank" rel="noreferrer">worldwide coverage</a>.</p>',20)])])}const p=t(a,[["render",n]]);export{v as __pageData,p as default};
